let maxD, power, i;
// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	ellipseMode(RADIUS);
	background(255);
	noStroke();
}

function draw() {
	maxD = dist(height / 2, height / 2, 0, 0);
	power = 1 + 5 * pow(0.5 * (1 + sin(radians(frameCount))), 3);
	for (i = 0; i < 4000; i++) {
		x = random(width);
		y = random(height);
		d = pow(dist(x, y, width / 2, height / 2) / maxD, 0.5);
		th = atan2(y - height / 2, x - width / 2);
		fth = (th * 3 + radians(frameCount * 2));
		fth2 = (th + radians(frameCount)) * 3;
		f = 0.5 * (1 + sin(d * TAU * 3 + fth));
		fd2 = 0.5 * (1 + sin(d * TAU * 7 + fth2 + radians(frameCount)));
		fill(255 * pow(f, power));
		circle(x, y, 10 * pow(fd2, 1));
	}
}
